1. import { ExecuteFunction, ExecutionArgs, ExecutionResult, IncrementalExecutionResult, ParseFunction, SubscribeFunction, ValidateFunction, ValidateFunctionParameter } from './graphql.js';
2. import { Plugin } from './plugin.js';
3. import { AsyncIterableIteratorOrValue, Maybe, PromiseOrValue } from './utils.js';
4. export type DefaultArgs = Record<string, unknown>;
5. export type SetSchemaFn = (newSchema: any) => void;
6. /**
7.  * The payload forwarded to the onSchemaChange hook.
8.  */
9. export type OnSchemaChangeEventPayload = {
10.     schema: any;
11.     replaceSchema: SetSchemaFn;
12. };
13. /**
14.  * Invoked each time the schema is changed via a setSchema call.
15.  */
16. export type OnSchemaChangeHook = (options: OnSchemaChangeEventPayload) => void;
17. export type OnContextErrorHandlerPayload = {
18.     /**
19.      * The context object at the "last working" state
20.      */
21.     context: Readonly<Record<string, unknown>>;
22.     /** The error or thing that got rejected or thrown */
23.     error: unknown;
24.     /** Overwrite the error or thing that got rejected or thrown. */
25.     setError: (err: unknown) => void;
26. };
27. export type OnContextErrorHandler = (options: OnContextErrorHandlerPayload) => PromiseOrValue<void>;
28. export type RegisterContextErrorHandler = (handler: OnContextErrorHandler) => void;
29. /**
30.  * Payload forwarded to the onPluginInit hook.
31.  */
32. export type OnPluginInitEventPayload<PluginContext extends Record<string, any>> = {
33.     /**
34.      * Register a new plugin.
35.      */
36.     addPlugin: (newPlugin: Plugin<PluginContext>) => void;
37.     /**
38.      * A list of all currently active plugins.
39.      */
40.     plugins: Plugin<PluginContext>[];
41.     /**
42.      * Set the GraphQL schema.
43.      */
44.     setSchema: SetSchemaFn;
45.     /**
46.      * Register an error handler used for context creation.
47.      */
48.     registerContextErrorHandler: RegisterContextErrorHandler;
49. };
50. /**
51.  * Invoked when a plugin is initialized.
52.  */
53. export type OnPluginInitHook<ContextType extends Record<string, any>> = (options: OnPluginInitEventPayload<ContextType>) => void;
54. /** onPluginInit */
55. export type OnEnvelopedHookEventPayload<ContextType> = {
56.     /**
57.      * Set the schema that should be used for execution.
58.      */
59.     setSchema: SetSchemaFn;
60.     /**
61.      * The context object.
62.      */
63.     context: Readonly<Maybe<ContextType>>;
64.     /**
65.      * Extend the context object with a partial.
66.      */
67.     extendContext: (contextExtension: Partial<ContextType>) => void;
68. };
69. export type OnEnvelopedHook<ContextType> = (options: OnEnvelopedHookEventPayload<ContextType>) => void;
70. export type OnParseEventPayload<ContextType> = {
71.     /**
72.      * The current context object.
73.      */
74.     context: Readonly<ContextType>;
75.     /**
76.      * Extend the context object with a partial.
77.      */
78.     extendContext: (contextExtension: Partial<ContextType>) => void;
79.     /**
80.      * The parameters that are passed to the parse call.
81.      */
82.     params: {
83.         source: string | any;
84.         options?: any;
85.     };
86.     /**
87.      * The current parse function
88.      */
89.     parseFn: ParseFunction;
90.     /**
91.      * Replace the current parse function
92.      */
93.     setParseFn: (newFn: ParseFunction) => void;
94.     /**
95.      * Set/overwrite the parsed document.
96.      * If a parsed document is set the call to the parseFn will be skipped.
97.      */
98.     setParsedDocument: (doc: any) => void;
99. };
100. export type AfterParseEventPayload<ContextType> = {
101.     /**
102.      * The current context object.
103.      */
104.     context: Readonly<ContextType>;
105.     /**
106.      * Extend the context object with a partial.
107.      */
108.     extendContext: (contextExtension: Partial<ContextType>) => void;
109.     /**
110.      * The result of the parse phase.
111.      */
112.     result: any | Error | null;
113.     /**
114.      * Replace the parse result with a new result.
115.      */
116.     replaceParseResult: (newResult: any | Error) => void;
117. };
118. /**
119.  * Hook that is invoked after the parse function has been invoked.
120.  */
121. export type AfterParseHook<ContextType> = (options: AfterParseEventPayload<ContextType>) => void;
122. /**
123.  * Hook that is invoked before the parse function is invoked.
124.  */
125. export type OnParseHook<ContextType> = (options: OnParseEventPayload<ContextType>) => void | AfterParseHook<ContextType>;
126. /**
127.  * Payload forwarded to the onValidate hook.
128.  */
129. export type OnValidateEventPayload<ContextType> = {
130.     /**
131.      * The current context object.
132.      */
133.     context: Readonly<ContextType>;
134.     /**
135.      * Extend the context object with a partial.
136.      */
137.     extendContext: (contextExtension: Partial<ContextType>) => void;
138.     /**
139.      * The parameters with which the validate function will be invoked.
140.      */
141.     params: ValidateFunctionParameter;
142.     /**
143.      * Register a validation rule that will be used for the validate invocation.
144.      */
145.     addValidationRule: (rule: any) => void;
146.     /**
147.      * The current validate function that will be invoked.
148.      */
149.     validateFn: ValidateFunction;
150.     /**
151.      * Overwrite the current validate function.
152.      */
153.     setValidationFn: (newValidate: ValidateFunction) => void;
154.     /**
155.      * Set a validation error result and skip the validate invocation.
156.      */
157.     setResult: (errors: readonly any[]) => void;
158. };
159. /**
160.  * Payload forwarded to the afterValidate hook.
161.  */
162. export type AfterValidateEventPayload<ContextType> = {
163.     /**
164.      * The current context object.
165.      */
166.     context: Readonly<ContextType>;
167.     /**
168.      * Extend the context object with a partial.
169.      */
170.     extendContext: (contextExtension: Partial<ContextType>) => void;
171.     /**
172.      * Whether the validation raised any errors or not.
173.      */
174.     valid: boolean;
175.     /**
176.      * An array of errors that were raised during the validation phase.
177.      * The array is empty if no errors were raised.
178.      */
179.     result: readonly Error[] | any[];
180.     /**
181.      * Replace the current error result with a new one.
182.      */
183.     setResult: (errors: Error[] | any[]) => void;
184. };
185. /**
186.  * AfterValidateHook is invoked after the validate function has been invoked.
187.  */
188. export type AfterValidateHook<ContextType> = (options: AfterValidateEventPayload<ContextType>) => void;
189. /**
190.  * The OnValidateHook is invoked before the validate function has been invoked.
191.  */
192. export type OnValidateHook<ContextType> = (options: OnValidateEventPayload<ContextType>) => void | AfterValidateHook<ContextType>;
193. /**
194.  * The payload forwarded to the onContextBuilding hook.
195.  */
196. export type OnContextBuildingEventPayload<ContextType> = {
197.     /**
198.      * The current context object.
199.      */
200.     context: Readonly<ContextType>;
201.     /**
202.      * Extend the context object with a partial.
203.      */
204.     extendContext: (contextExtension: Partial<ContextType>) => void;
205.     /**
206.      * Prevent calls on any further context building hooks.
207.      */
208.     breakContextBuilding: () => void;
209. };
210. /**
211.  * The payload forwarded to the afterContextBuilding hook.
212.  */
213. export type AfterContextBuildingEventPayload<ContextType> = {
214.     /**
215.      * The current context object.
216.      */
217.     context: ContextType;
218.     /**
219.      * Extend the context object with a partial.
220.      */
221.     extendContext: (contextExtension: Partial<ContextType>) => void;
